def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    my_d = me.count('D')

    # Endgame: defect aggressively in the last rounds
    if n >= 99:
        return 'D'
    if n >= 95:
        if rng.random() < 0.5:
            return 'D'
    elif n >= 90:
        if rng.random() < 0.2:
            return 'D'

    # If opponent is a consistent defector, defect always
    if n >= 5 and op_d >= n - 2:
        return 'D'
    if op_d > n * 0.5:
        return 'D'

    # Recent behavior window
    window = min(10, n)
    recent_op = op[-window:]
    recent_op_d = recent_op.count('D')
    recent_me = me[-window:]
    recent_me_d = recent_me.count('D')

    last_me = me[-1]
    last_op = op[-1]

    # Opponent defected last round
    if last_op == 'D':
        # Only retaliate if they have a sustained pattern of defection
        if op_d >= 5 and recent_op_d >= 3:
            return 'D'
        # Otherwise forgive to avoid retaliation spirals
        return 'C'

    # Opponent cooperated last round
    if last_me == 'D':
        # We just exploited them. If they remain cooperative, keep exploiting.
        if op_d <= n * 0.2:
            return 'D'
        return 'C'

    # Both cooperated last round.
    # Probe if opponent has been very cooperative and we haven't defected recently.
    if recent_op_d == 0 and recent_me_d == 0 and n >= 20:
        if rng.random() < 0.05:
            return 'D'

    return 'C'
